const jwt = require('jsonwebtoken');

// ==========================================
// 核心路径与本地数据配置
// ==========================================
const DATA_DIR = path.join(__dirname, '../data');
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

const DB_PATH = path.join(DATA_DIR, 'kunlun_agent.db'); // 暂未使用，保留扩展
const WX_DB_PATH = path.join(DATA_DIR, 'wx_mock.db'); // 用户可通过 UI 自定义覆盖
const KNOWLEDGE_DIR = path.join(DATA_DIR, 'knowledge');
if (!fs.existsSync(KNOWLEDGE_DIR)) fs.mkdirSync(KNOWLEDGE_DIR, { recursive: true });

// 📚 初始化 RAG SQLite FTS5 本地向量/全文检索库
const RAG_DB_PATH = path.join(DATA_DIR, 'rag_knowledge.db');
const ragDb = new sqlite3.Database(RAG_DB_PATH, (err) => {
  if (err) console.error('[RAG Engine] Failed to open rag_knowledge.db', err);
  else {
    ragDb.run(`
      CREATE VIRTUAL TABLE IF NOT EXISTS knowledge_chunks USING fts5(
        filename, 
        chunk_index, 
        content,
        tokenize='porter'
      )
    `);
    console.log('[RAG Engine] FTS5 Knowledge Base Database initialized.');
  }
});

// 分块函数 (Chunking) 供 RAG 入库使用
function chunkText(text, chunkSize = 500, overlap = 100) {
  const chunks = [];
  let i = 0;
  while (i < text.length) {
    chunks.push(text.slice(i, i + chunkSize));
    i += (chunkSize - overlap);
  }
  return chunks;
}

const JWT_SECRET_FILE = path.join(DATA_DIR, 'jwt_secret.txt');

